/// <summary>
/// MPJ_24248 Pricing Data Extract DCP 28/07/2022
/// </summary>
class METPriceChangeTrackTaskService extends SysOperationServiceBase
{
    Batch           batchTask;
    Batch           batchTaskCurrent;
    BatchHeader     batchHeader;
    RefRecId        batchJobId;
    RefRecId        headerTaskId;
    boolean         isExecutingInBatch, isMainBatchTask;
    METBundleCount  bundleCount;
    METTaskGuid     taskGuid;
    UserConnection  secondConnection;
    boolean         showValidation;
 
    METPriceChangeTrackContract    dataContract;
    RecordInsertList            priceReportItemTaskInsertList;

}

Method.Source:
    /// <summary>
    /// processing logic
    /// </summary>
    /// <param name = "_dataContract">The data contract</param>
    public void process(METPriceChangeTrackContract _dataContract)
    {
        #OCCRetryCount

        try
        {
            this.initialise(_dataContract);

            if(!this.validate())
            {
                error("@MET:PriceChangeTrackBatchTaskFailed");
                
                if(isExecutingInBatch)
                {
                    //ensure batch status is "Error"
                    throw Exception::Error;
                }
                else
                {
                    //dont throw error when run from GUI
                    return;
                }
            }

            this.processTask(true);

            if(isMainBatchTask)
            {
                //last run of main task thread to make sure all records have been processed
                this.processTask(false);
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error("@MET:PriceChangeTrackBatchTaskFailed");
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                error("@MET:PriceChangeTrackBatchTaskFailed");
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::Deadlock)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error("@MET:PriceChangeTrackBatchTaskFailed");
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                error("@MET:PriceChangeTrackBatchTaskFailed");
                throw Exception::Deadlock;
            }
        }
        catch
        {
            error("@MET:PriceChangeTrackBatchTaskFailed");
            throw Exception::Error;
            
        }
    }

    /// <summary>Initialise global variables</summary>
    /// <param name = "_dataContract">The data contract</param>
    public void initialise(METPriceChangeTrackContract _dataContract)
    {
        dataContract        = _dataContract;
        
        isMainBatchTask     = dataContract.parmIsMainBatchTask();
        bundleCount         = dataContract.parmBundleCount();
        batchTaskCurrent    = this.getCurrentBatchTask();
        batchJobId          = batchTaskCurrent.BatchJobId;
        headerTaskId        = batchTaskCurrent.RecId;
        batchHeader         = BatchHeader::construct(batchJobId);
        isExecutingInBatch  = batchTaskCurrent ? true : false;
        taskGuid            = str2Guid(dataContract.parmTaskGuidStr());
        secondConnection    = new UserConnection();
        showValidation      = dataContract.parmShowValidation() == NoYes::Yes;

    }

    /// <summary>Check that process should run</summary>
    /// <returns>The result of the validation</returns>
    public boolean validate()
    {
        boolean Ok = true;

        if(!taskGuid)
        {
            Ok = checkFailed("@MET:TaskGuidMissing");
        }

        return Ok;
    }

    /// <summary>Process the batch tasks</summary>
    /// <param name = "_readPast">Table read past setting</param>
    public void processTask(boolean _readPast)
    {
        METPriceChangeTracking  priceChangeTracking;	       //table used for top pick list
        
        priceChangeTracking.setConnection(secondConnection);
        priceChangeTracking.readPast(_readPast);              // skip or don't skip locked records

        do
        {
            secondConnection.ttsbegin();
                            
            select firstOnly pessimisticlock priceChangeTracking;

            if(priceChangeTracking)
            {
                METPriceChangeTrack priceChangeTrack = METPriceChangeTrackFactory::newFromPriceChangeType(priceChangeTracking.ChangeType);
                priceChangeTrack.initInstance(priceChangeTracking, showValidation);
                priceChangeTrack.process();

                priceChangeTracking.delete();
                
            }   

            secondConnection.ttscommit();
        }
        while(priceChangeTracking);
    }

/// <summary>Constuct new object</summary>
/// <returns>New Service Object</returns>
public static METPriceChangeTrackTaskService construct()
{
    return new METPriceChangeTrackTaskService();
}

    /// <summary>
    /// Constuct and run a METPriceChangeTrackTaskService. Used when process is run from GUI (not in Batch mode)
    /// </summary>
    /// <param name = "_serializedContractCon">Serialised data contract</param>
    public static void processAsync(container _serializedContractCon)	//must have Container as parameter
    {
        METPriceChangeTrackTaskService  PriceChangeTrackTaskService;
        METPriceChangeTrackContract     dataContract;
        Object  				        deserializedContract;
        str                             serializedContract;

        serializedContract      = conPeek(_serializedContractCon,1);
        deserializedContract    = FormJsonSerializer::deserializeObject(classIdGet(dataContract), serializedContract);
        dataContract            = deserializedContract as METPriceChangeTrackContract;

        PriceChangeTrackTaskService = METPriceChangeTrackTaskService::construct();
        PriceChangeTrackTaskService.process(dataContract);
    }
